api.look('sketch');
const cx = api.w/2, cy = 380;
const k = api.seg(t, 0, 1.2);
api.ellipse(cx, cy+150, 120, 14, {c:'dim', k, a:0.5});
api.rect(cx-70, cy-30, 140, 150, {r:28, c:'fg', w:4, fill:'accent', k});
api.rect(cx-55, cy-110, 110, 80, {r:22, c:'fg', w:4, fill:'ink', k:api.seg(t,0.4,1.4)});
const bl = api.pulse(t, 0.8) > 0.5 ? 0 : 1;
api.circle(cx-20, cy-72, 9, {c:'fg', fill:'fg', k:api.seg(t,1,1.5)});
api.circle(cx+20, cy-72, 9, {c:'fg', fill:'fg', k:api.seg(t,1,1.5)});
api.line(cx, cy-110, cx, cy-145, {c:'fg', w:4, k:api.seg(t,1,1.6)});
