api.circle(cx-85, cy+140, 22, {c:'fg', w:4, fill:'ink', k:api.seg(t,0.8,1.6)});
api.circle(cx+85, cy+140, 22, {c:'fg', w:4, fill:'ink', k:api.seg(t,0.8,1.6)});
api.kinetic('Plant Bot', cx, 150, {mode:'pop', k:api.seg(t,1.2,2.4), size:40});
api.say('A tiny plant-watering robot', 0.3, 3.3);

api.look('sketch');
const cx = api.w/2, cy = 400;
const rk = api.seg(t, 0, 1.2);
api.cam(api.lerp(0,-20,api.ease(api.seg(t,0,6))), 0, 1, 0);
api.rect(cx-110, cy-30, 120, 150, {r:28, c:'fg', w:4, fill:'accent', k:1});
api.rect(cx-95, cy-110, 100, 80, {r:22, c:'fg', w:4, fill:'ink'});
api.circle(cx-65, cy-72, 8, {c:'fg', fill:'fg'});
api.circle(cx-30, cy-72, 8, {c:'fg', fill:'fg'});
api.circle(cx-90, cy+140, 20, {c:'fg', w:4, fill:'ink'});
api.circle(cx-10, cy+140, 20, {c:'fg', w:4, fill:'ink'});
api.path('M10 40 C60 40 70 70 90 110', {x:cx, y:cy-40, c:'a2', w:5, k:api.seg(t,0.6,1.6)});
const px = cx+110, py = cy+80;
api.path('M-40 0 L40 0 L30 70 L-30 70 Z', {x:px, y:py+40, c:'fg', w:4, fill:'#c98a5a', k:api.seg(t,0.3,1.2)});
const lk = api.seg(t,1.5,5);
api.swarm(30, t, {mode:'fall', cx:px-30, cy:cy+20, rx:6, ry:70, c:'a2', size:4, k:api.seg(t,1.5,2)});
api.path('M0 0 C0 -40 -10 -60 -30 -80 M0 0 C0 -30 10 -60 35 -75 M0 -30 C-5 -50 0 -70 0 -95', {x:px, y:py+40, c:'good', w:5, k:api.seg(t,2,4)});
api.callout('Waters each plant', px, py+30, 100, cy+230, {k:api.seg(t,3,4.5)});
api.say('It rolls up and waters', 0.4, 5.5);

api.look('sketch');
const cx = api.w/2, cy = 380;
const drain = api.seg(t, 0.8, 4.5);
const lvl = 1 - drain*0.85;
api.rect(cx-80, cy-140, 160, 280, {r:26, c:'fg', w:5, fill:'ink'});
const hh = 250*lvl;
api.clipRect(cx-75, cy-135, 150, 270, ()=>{
  c.fillStyle = '#1d8fb3';
  c.globalAlpha = 0.85;
  c.beginPath();
  for(let x=0;x<=150;x+=5){
    const y = cy+130-hh + api.wave(x,t,60,1.5,5);
    x?c.lineTo(cx-75+x,y):c.moveTo(cx-75+x,y);
  }
  c.lineTo(cx+75,cy+140); c.lineTo(cx-75,cy+140); c.closePath(); c.fill();
  c.globalAlpha = 1;
});
api.label('Water tank', cx, cy-180, {k:api.seg(t,0,1)});
api.counter(Math.round(lvl*100), cx, cy+210, {suf:'%', size:44, k:1});
const low = lvl < 0.3;
if (low) api.scribble(cx, cy+10, 110, 170, {c:'bad', k:api.seg(t,4.3,5.2)});
api.say('It watches its own tank', 0.4, 5.5);

api.look('sketch');
const cx = api.w/2, cy = 330;
const pr = api.pulse(t, 1.5);
api.glow(cx, cy+60, 140+pr*30, {c:'bad'});
api.rect(cx-80, cy-140, 160, 280, {r:26, c:'fg', w:5, fill:'ink'});
api.rect(cx-70, cy+90, 140, 40, {r:10, c:'a2', fill:'a2', w:2});
api.shape('bell', cx+100, cy-130, 70+pr*8, {c:'bad', fill:'bad', k:api.seg(t,0.3,1.2)});
api.shape('phone', cx, cy+300, 120, {c:'fg', k:api.seg(t,1.5,2.5)});
api.arrow(cx+90, cy-90, cx+30, cy+250, {bend:-0.3, c:'accent', k:api.seg(t,1.2,2.4)});
api.kinetic('Tank low!', cx, 120, {mode:'drop', k:api.seg(t,2.5,3.5), size:42, hot:'bad'});
api.say('It tells you when it is low', 0.4, 5.5);

api.look('sketch');
const cx = api.w/2, cy = 380;
const f = api.seg(t, 1, 4);
api.cam(0, 0, api.lerp(1, 1.1, api.ease(api.seg(t,0,6))), 0);
api.rect(cx-80, cy-140, 160, 280, {r:26, c:'fg', w:5, fill:'ink'});
api.clipRect(cx-75, cy-135, 150, 270, ()=>{
  c.fillStyle = '#1d8fb3'; c.globalAlpha = 0.85;
  c.fillRect(cx-75, cy+135-270*(0.1+0.85*api.ease(f)), 150, 270);
  c.globalAlpha = 1;
});
api.swarm(25, t, {mode:'fall', cx, cy:cy-200, rx:10, ry:60, c:'a2', size:4, k:api.seg(t,0.8,1.5)});
api.shape('check', cx, cy+10, 90, {c:'good', w:8, k:api.seg(t,4,5)});
api.shape('leaf', cx-130, cy-170, 50, {c:'good', fill:'good', k:api.seg(t,4.2,5)});
api.shape('leaf', cx+130, cy-170, 50, {c:'good', fill:'good', k:api.seg(t,4.4,5.2)});
api.kinetic('Happy plants', cx, 120, {mode:'rise', k:api.seg(t,4,5), size:40});
api.say('You refill, plants stay happy', 0.4, 5.5);
